#import <Foundation/Foundation.h>
#import <Metal/Metal.h>
#include <string.h>
int main(int argc,const char**argv){@autoreleasepool{
 NSString*mode=argc>1?@(argv[1]):@"compute";NSMutableArray*results=[NSMutableArray array];
 for(id<MTLDevice>d in MTLCopyAllDevices()){
  if(getenv("D500_MIN_DEVICE")&&d.registryID!=strtoull(getenv("D500_MIN_DEVICE"),0,10))continue;
  NSError*err=nil;MTLCompileOptions*opt=[MTLCompileOptions new];opt.languageVersion=MTLLanguageVersion2_0;
  NSString*source=@"#include <metal_stdlib>\nusing namespace metal;vertex float4 v(uint i[[vertex_id]]){float2 a[3]={float2(-1,-1),float2(3,-1),float2(-1,3)};return float4(a[i],0,1);} fragment float4 f(float4 p[[position]],texture2d_ms<float,access::read> t[[texture(0)]]){return t.read(uint2(p.xy),0);} kernel void c(texture2d_ms<float,access::read> t[[texture(0)]],device float4*out[[buffer(0)]],uint2 p[[thread_position_in_grid]]){out[p.y*256+p.x]=t.read(p,0);}";
  if([mode isEqual:@"compute-serial"])source=[source stringByReplacingOccurrencesOfString:@"out[p.y*256+p.x]=t.read(p,0);" withString:@"for(uint y=0;y<128;y++)for(uint x=0;x<256;x++)out[y*256+x]=t.read(uint2(x,y),0);"];
  if([mode containsString:@"fixed"])source=[source stringByReplacingOccurrencesOfString:@"t.read(uint2(p.xy),0)" withString:@"t.read(uint2(0,0),0)"];
  if([mode containsString:@"constant"])source=[source stringByReplacingOccurrencesOfString:@"return t.read(uint2(p.xy),0);" withString:@"return float4(0,1,0,1);"];
  id<MTLLibrary>lib=[d newLibraryWithSource:source options:opt error:&err];if(!lib){fprintf(stderr,"library:%s\n",err.description.UTF8String);return 2;}
  MTLTextureDescriptor*td=[MTLTextureDescriptor texture2DDescriptorWithPixelFormat:MTLPixelFormatRGBA8Unorm width:256 height:128 mipmapped:NO];td.textureType=MTLTextureType2DMultisample;td.sampleCount=4;td.storageMode=MTLStorageModePrivate;td.usage=MTLTextureUsageRenderTarget|MTLTextureUsageShaderRead;
  id<MTLTexture>ms=[d newTextureWithDescriptor:td];td.textureType=MTLTextureType2D;td.sampleCount=1;id<MTLTexture>dst=[d newTextureWithDescriptor:td];
  NSUInteger bytes=[mode hasPrefix:@"compute"]?256*128*16:256*128*4;id<MTLBuffer>out=[d newBufferWithLength:bytes options:MTLResourceStorageModeManaged];memset(out.contents,0xa5,bytes);[out didModifyRange:NSMakeRange(0,bytes)];
  id<MTLCommandQueue>q=[d newCommandQueue];id<MTLCommandBuffer>cb=[q commandBuffer];MTLRenderPassDescriptor*pass=[MTLRenderPassDescriptor renderPassDescriptor];pass.colorAttachments[0].texture=ms;pass.colorAttachments[0].clearColor=MTLClearColorMake(0,1,0,1);pass.colorAttachments[0].loadAction=MTLLoadActionClear;pass.colorAttachments[0].storeAction=MTLStoreActionStore;
  if([mode isEqual:@"hardware"]){pass.colorAttachments[0].resolveTexture=dst;pass.colorAttachments[0].storeAction=MTLStoreActionStoreAndMultisampleResolve;}
  id<MTLFence>fence=getenv("D500_MIN_BARRIER")?[d newFence]:nil;id<MTLRenderCommandEncoder>re=[cb renderCommandEncoderWithDescriptor:pass];if(fence)[re updateFence:fence afterStages:MTLRenderStageFragment];[re endEncoding];
  if([mode hasPrefix:@"compute"]){id<MTLComputePipelineState>cs=[d newComputePipelineStateWithFunction:[lib newFunctionWithName:@"c"] error:&err];if(!cs){fprintf(stderr,"compute:%s\n",err.description.UTF8String);return 3;}id<MTLComputeCommandEncoder>ce=[cb computeCommandEncoder];[ce setComputePipelineState:cs];if(fence)[ce waitForFence:fence];[ce setTexture:ms atIndex:0];if(fence){[ce useResource:ms usage:MTLResourceUsageRead];[ce memoryBarrierWithScope:MTLBarrierScopeTextures];}[ce setBuffer:out offset:0 atIndex:0];if([mode isEqual:@"compute-serial"])[ce dispatchThreadgroups:MTLSizeMake(1,1,1) threadsPerThreadgroup:MTLSizeMake(1,1,1)];else [ce dispatchThreadgroups:MTLSizeMake(8,16,1) threadsPerThreadgroup:MTLSizeMake(32,8,1)];[ce endEncoding];}
  else if(![mode isEqual:@"hardware"]){MTLRenderPipelineDescriptor*pd=[MTLRenderPipelineDescriptor new];pd.vertexFunction=[lib newFunctionWithName:@"v"];pd.fragmentFunction=[lib newFunctionWithName:@"f"];pd.colorAttachments[0].pixelFormat=MTLPixelFormatRGBA8Unorm;id<MTLRenderPipelineState>ps=[d newRenderPipelineStateWithDescriptor:pd error:&err];if(!ps){fprintf(stderr,"render:%s\n",err.description.UTF8String);return 4;}pass=[MTLRenderPassDescriptor renderPassDescriptor];pass.colorAttachments[0].texture=dst;pass.colorAttachments[0].loadAction=MTLLoadActionClear;pass.colorAttachments[0].clearColor=MTLClearColorMake(1,0,0,1);pass.colorAttachments[0].storeAction=MTLStoreActionStore;re=[cb renderCommandEncoderWithDescriptor:pass];[re setRenderPipelineState:ps];[re setFragmentTexture:ms atIndex:0];[re drawPrimitives:MTLPrimitiveTypeTriangle vertexStart:0 vertexCount:3];[re endEncoding];}
  id<MTLBlitCommandEncoder>bl=[cb blitCommandEncoder];if(![mode hasPrefix:@"compute"])[bl copyFromTexture:dst sourceSlice:0 sourceLevel:0 sourceOrigin:MTLOriginMake(0,0,0) sourceSize:MTLSizeMake(256,128,1) toBuffer:out destinationOffset:0 destinationBytesPerRow:1024 destinationBytesPerImage:0];[bl synchronizeResource:out];[bl endEncoding];[cb commit];[cb waitUntilCompleted];
  NSUInteger bad=0,first=0;NSMutableArray*pixel=[NSMutableArray array];for(NSUInteger i=0;i<256*128;i++){BOOL good;if([mode hasPrefix:@"compute"]){float*p=out.contents;good=p[i*4]==0&&p[i*4+1]==1&&p[i*4+2]==0&&p[i*4+3]==1;}else{uint8_t*p=out.contents;good=p[i*4]==0&&p[i*4+1]==255&&p[i*4+2]==0&&p[i*4+3]==255;}if(!good){if(!bad)first=i;bad++;}}
  for(int j=0;j<4;j++)[pixel addObject:[mode hasPrefix:@"compute"]?@(((float*)out.contents)[first*4+j]):@(((uint8_t*)out.contents)[first*4+j])];
  NSDictionary*result=@{@"mode":mode,@"gpu":@(d.registryID),@"status":@(cb.status),@"badCount":@(bad),@"firstBad":@(first),@"pixel":pixel,@"error":cb.error.description?:@""};puts([[NSString alloc]initWithData:[NSJSONSerialization dataWithJSONObject:result options:0 error:nil]encoding:NSUTF8StringEncoding].UTF8String);fflush(stdout);[results addObject:result];if(bad||cb.error)return 5;
 }return 0;}}
